import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for i in [1,2,3,4,6,7,8]:
    try:
        dfs[i] = pd.read_csv(f"experiment_{i}_csv")
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(dfs[i].columns)}")
        print(dfs[i].describe().round(2))
        print("\nCorrelations:")
        print(dfs[i].corr(numeric_only=True).round(3))
    except Exception as e:
        print(f"Experiment {i}: {e}")

# Check if we have experiment labels or treatment info
for i in [1,2,3,4,6,7,8]:
    if i in dfs:
        print(f"\n--- Exp {i} first 3 rows ---")
        print(dfs[i].head(3))
